from __future__ import annotations

from app.models.enums import AuthorityType, Provider

#: Bremen — the first Bundesland catalogued, and the smallest.
#:
#: Generated by ``python -m scripts.discover_bremen`` from the state's own
#: portal (service.bremen.de), which lists every authority offering appointment
#: booking. Re-run that script to refresh; do not hand-edit.
#:
#: Every entry is ``scan_enabled=False``. The offices are real, the mandant ids
#: are real, and the TEVIS adapter would handle them — but termin.bremen.de
#: publishes ``Disallow: /`` for every agent and its API refuses access without
#: credentials. So Bremen is listed and bookable by hand-off, not scanned.
#: Granting scanning is one flag per row once Bremen gives permission.
BREMEN_BLOCKED_REASON = (
    "termin.bremen.de untersagt automatisiertes Abrufen (robots.txt); "
    "Terminüberwachung erst nach Freigabe durch die Behörde"
)

#: All Bremen offices sit on one TEVIS instance, distinguished by the ``md``
#: mandant parameter. Note the ``/termine`` path prefix: the instance is not
#: mounted at the host root.
BREMEN_BASE_URL = "https://termin.bremen.de/termine"

